import { useEffect, useState } from 'react';
import { Link, useNavigate, useOutletContext, useSearchParams } from 'react-router-dom';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Bell, CalendarClock, Check, ClipboardCheck, History, ImagePlus, PackageCheck, Plus, Search, ShieldAlert, Tractor, Trash2, UserCog, UserRound, MapPin } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { api, uploadImage, type Booking, type Location, type Machinery, type NotificationItem, type Page, type User } from '../lib/api';
import { Badge, Button, Card, EmptyState, ErrorState, Field, formatDate, formatINR, inputClass, LoadingState, SectionHeading, StatusBadge } from '../components/ui';
import { useToast } from '../components/Toast';

const today = () => new Date(Date.now() - new Date().getTimezoneOffset() * 60_000).toISOString().slice(0, 10);
const locationPayload = (village: string, taluka: string, district: string, state: string) => ({ village: village.trim(), taluka: taluka.trim(), district: district.trim(), state: state.trim() || 'Maharashtra' });

export function ProfilePage() {
  const queryClient = useQueryClient();
  const { showToast } = useToast();
  const { t, i18n } = useTranslation();
  const me = useQuery({ queryKey: ['me'], queryFn: () => api<{ data: { user: User } }>('/auth/me'), retry: false });
  const user = me.data?.data.user;
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<'en' | 'mr' | 'hi'>('en');
  const [farmName, setFarmName] = useState('');
  const [village, setVillage] = useState('');
  const [taluka, setTaluka] = useState('');
  const [district, setDistrict] = useState('');
  const [state, setState] = useState('Maharashtra');
  const [locationPoint, setLocationPoint] = useState<Location['point']>();
  const [skills, setSkills] = useState('');
  const [experienceYears, setExperienceYears] = useState('0');
  const [available, setAvailable] = useState(false);
  const [availabilityDates, setAvailabilityDates] = useState('');
  const [expectedWage, setExpectedWage] = useState('');
  const [bio, setBio] = useState('');
  const [providerName, setProviderName] = useState('');
  const [providerDescription, setProviderDescription] = useState('');

  useEffect(() => {
    if (!user) return;
    setName(user.name); setLanguage(user.preferredLanguage ?? 'en');
    setFarmName(user.farmerProfile?.farmName ?? '');
    const loc = user.labourerProfile?.serviceArea ?? user.farmerProfile?.location ?? user.providerProfile?.serviceArea;
    setVillage(loc?.village ?? ''); setTaluka(loc?.taluka ?? ''); setDistrict(loc?.district ?? ''); setState(loc?.state ?? 'Maharashtra'); setLocationPoint(loc?.point);
    setSkills((user.labourerProfile?.skills ?? []).join(', ')); setExperienceYears(String(user.labourerProfile?.experienceYears ?? 0));
    setAvailable(Boolean(user.labourerProfile?.available));
    setAvailabilityDates((user.labourerProfile?.availabilityDates ?? []).map((date) => String(date).slice(0, 10)).join(', '));
    setExpectedWage(user.labourerProfile?.expectedWage ? String(user.labourerProfile.expectedWage.amount) : '');
    setBio(user.labourerProfile?.bio ?? ''); setProviderName(user.providerProfile?.displayName ?? ''); setProviderDescription(user.providerProfile?.description ?? '');
  }, [user]);

  const captureCurrentLocation = () => {
    if (!('geolocation' in navigator)) { showToast('This browser does not support location access. Enter your service area manually instead.', 'error'); return; }
    navigator.geolocation.getCurrentPosition(
      (position) => {
        setLocationPoint({ type: 'Point', coordinates: [position.coords.longitude, position.coords.latitude] });
        showToast('Current location selected. Save your profile to use it for nearby matching.');
      },
      (error) => showToast(error.code === error.PERMISSION_DENIED ? 'Location permission was denied. You can continue with manual location entry.' : 'Could not retrieve your location. Please try again or enter it manually.', 'error'),
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 30000 },
    );
  };

  const save = useMutation({
    mutationFn: () => {
      const patch: Record<string, unknown> = { name, preferredLanguage: language };
      const baseLocation = locationPayload(village, taluka, district, state);
      const location = { ...baseLocation, ...(locationPoint ? { point: locationPoint } : {}) };
      if (user?.roles.includes('farmer')) patch.farmerProfile = { farmName, location };
      if (user?.roles.includes('labourer')) patch.labourerProfile = { skills: skills.split(',').map((x) => x.trim()).filter(Boolean), experienceYears: Number(experienceYears), available, availabilityDates: availabilityDates.split(/[\n,]/).map((x) => x.trim()).filter(Boolean).slice(0, 60), bio, serviceArea: location, ...(expectedWage.trim() ? { expectedWage: { amount: Number(expectedWage), basis: 'worker_day', currency: 'INR' } } : {}) };
      if (user?.roles.includes('machinery_provider')) patch.providerProfile = { displayName: providerName, description: providerDescription, serviceArea: location };
      return api<{ data: { user: User } }>('/auth/me', { method: 'PATCH', body: patch });
    },
    onSuccess: async (result) => { await i18n.changeLanguage(language); localStorage.setItem('ks.language', language); queryClient.setQueryData(['me'], result); await queryClient.invalidateQueries(); showToast('Profile saved successfully.'); },
    onError: (error) => showToast((error as Error).message, 'error'),
  });
  const activateRole = useMutation({
    mutationFn: (role: 'farmer' | 'labourer' | 'machinery_provider') => api<{ data: { user: User } }>('/auth/activate-role', { method: 'POST', body: { role } }),
    onSuccess: async (result) => { queryClient.setQueryData(['me'], result); await queryClient.invalidateQueries(); showToast('Role enabled. Complete the profile fields below.'); },
    onError: (error) => showToast((error as Error).message, 'error'),
  });
  if (me.isLoading) return <LoadingState/>;
  if (me.error || !user) return <ErrorState message={(me.error as Error)?.message ?? 'Your profile could not be loaded.'} onRetry={() => void me.refetch()}/>;
  return <>
    <SectionHeading eyebrow="Account" title="Profile & settings" description="Manage your personal details, language and the roles available in your account."/>
    <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
      <Card className="p-5 sm:p-6">
        <h2 className="text-lg font-extrabold text-ink">Personal details</h2>
        <form className="mt-5 space-y-4" onSubmit={(e) => { e.preventDefault(); if (!name.trim()) return; save.mutate(); }}>
          <Field label="Full name" required><input className={inputClass} required minLength={2} maxLength={100} value={name} onChange={(e) => setName(e.target.value)}/></Field>
          <div className="grid gap-4 sm:grid-cols-2"><Field label="Email address"><input className={`${inputClass} bg-paper`} readOnly value={user.email ?? 'Not provided'}/></Field><Field label="Mobile number"><input className={`${inputClass} bg-paper`} readOnly value={user.mobile ?? 'Not provided'}/></Field></div>
          <Field label="Preferred language"><select className={inputClass} value={language} onChange={(e) => setLanguage(e.target.value as 'en'|'mr'|'hi')}><option value="en">English</option><option value="mr">मराठी</option><option value="hi">हिन्दी</option></select></Field>
          {(user.roles.includes('labourer') || user.roles.includes('machinery_provider')) && <div className="flex flex-col gap-3 rounded-xl border border-line bg-paper p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold text-ink">Nearby matching location</p><p className="mt-1 text-xs leading-5 text-muted">Use your current location to improve proximity results. Location is requested only after you click, and precise coordinates are not shown on public profiles.</p><p className="mt-1 text-xs font-semibold text-forest">{locationPoint ? 'Coordinates selected for this profile' : 'No coordinates saved; manual service-area search still works.'}</p></div><Button type="button" variant="secondary" onClick={captureCurrentLocation}><MapPin size={16}/>Use current location</Button></div>}
          {user.roles.includes('farmer') && <div className="space-y-4 rounded-2xl border border-line p-4"><h3 className="font-bold text-ink">Farmer details</h3><Field label="Farm name"><input className={inputClass} value={farmName} onChange={(e) => setFarmName(e.target.value)} maxLength={120}/></Field><LocationFields {...{village,setVillage,taluka,setTaluka,district,setDistrict,state,setState}}/></div>}
          {user.roles.includes('labourer') && <div className="space-y-4 rounded-2xl border border-line p-4"><h3 className="font-bold text-ink">Labourer profile</h3><Field label="Skills (comma separated)" hint="For example: harvesting, sowing, weeding"><input className={inputClass} value={skills} onChange={(e) => setSkills(e.target.value)} maxLength={1200}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Years of experience"><input type="number" min="0" max="80" className={inputClass} value={experienceYears} onChange={(e) => setExperienceYears(e.target.value)}/></Field><Field label="Expected daily wage (₹)"><input type="number" min="0" max="10000000" className={inputClass} value={expectedWage} onChange={(e) => setExpectedWage(e.target.value)} placeholder="Optional"/></Field></div><Field label="About your experience"><textarea rows={3} className={`${inputClass} py-3`} value={bio} onChange={(e) => setBio(e.target.value)} maxLength={800}/></Field><label className="flex cursor-pointer items-center gap-3 rounded-xl bg-forest-light/60 p-3 text-sm font-semibold text-forest-dark"><input type="checkbox" className="h-4 w-4 accent-forest" checked={available} onChange={(e) => setAvailable(e.target.checked)}/>I am currently available for agricultural work</label><Field label="Specific available dates (optional)" hint="Enter dates as YYYY-MM-DD, separated by commas. If left blank, your availability toggle applies generally."><input className={inputClass} value={availabilityDates} onChange={(e) => setAvailabilityDates(e.target.value)} placeholder="2026-10-28, 2026-10-30"/></Field><LocationFields {...{village,setVillage,taluka,setTaluka,district,setDistrict,state,setState}}/></div>}
          {user.roles.includes('machinery_provider') && <div className="space-y-4 rounded-2xl border border-line p-4"><h3 className="font-bold text-ink">Machinery provider profile</h3><Field label="Display / business name"><input className={inputClass} value={providerName} onChange={(e) => setProviderName(e.target.value)} maxLength={120}/></Field><Field label="Description"><textarea rows={3} className={`${inputClass} py-3`} value={providerDescription} onChange={(e) => setProviderDescription(e.target.value)} maxLength={1000}/></Field><LocationFields {...{village,setVillage,taluka,setTaluka,district,setDistrict,state,setState}}/></div>}
          <div className="flex justify-end"><Button type="submit" loading={save.isPending}>Save profile</Button></div>
        </form>
      </Card>
      <div className="space-y-5"><Card className="p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-forest-light text-forest"><UserRound size={20}/></span><div><h2 className="font-extrabold text-ink">Your account roles</h2><p className="mt-1 text-xs text-muted">Add a role to use more marketplace features.</p></div></div><div className="mt-4 space-y-3">{([{key:'farmer',title:'Farmer',text:'Post farm jobs and request machinery.'},{key:'labourer',title:'Labourer',text:'Apply for work and respond to offers.'},{key:'machinery_provider',title:'Machinery provider',text:'List agricultural equipment and handle bookings.'}] as const).map((role) => <div key={role.key} className="flex items-center justify-between gap-3 rounded-xl border border-line p-3"><div><p className="text-sm font-bold text-ink">{role.title} {user.roles.includes(role.key) && <Badge>Enabled</Badge>}</p><p className="mt-1 text-xs leading-5 text-muted">{role.text}</p></div>{user.roles.includes(role.key) ? <Check size={18} className="shrink-0 text-forest"/> : <Button size="small" variant="secondary" onClick={() => activateRole.mutate(role.key)} loading={activateRole.isPending}>Enable</Button>}</div>)}</div></Card><Card className="p-5 sm:p-6"><div className="flex gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-amber-50 text-amber-800"><ShieldAlert size={18}/></span><div><h2 className="font-extrabold text-ink">Privacy reminder</h2><p className="mt-1 text-sm leading-6 text-muted">Use your general village or service area for discovery. Kisan Sahayak does not display private home coordinates in public worker cards. Payments are recorded outside the platform.</p></div></div></Card></div>
    </div>
  </>;
}

function LocationFields(props: { village: string; setVillage: (value: string) => void; taluka: string; setTaluka: (value: string) => void; district: string; setDistrict: (value: string) => void; state: string; setState: (value: string) => void }) {
  return <div className="grid gap-3 sm:grid-cols-2"><Field label="Village"><input className={inputClass} maxLength={100} value={props.village} onChange={(e) => props.setVillage(e.target.value)}/></Field><Field label="Taluka"><input className={inputClass} maxLength={100} value={props.taluka} onChange={(e) => props.setTaluka(e.target.value)}/></Field><Field label="District"><input className={inputClass} maxLength={100} value={props.district} onChange={(e) => props.setDistrict(e.target.value)}/></Field><Field label="State"><input className={inputClass} maxLength={100} value={props.state} onChange={(e) => props.setState(e.target.value)}/></Field></div>;
}

type ListingInput = { category: string; name: string; model: string; description: string; photos: string; village: string; taluka: string; district: string; state: string; amount: string; basis: 'hour_rental'|'day_rental'|'booking'|'acre'; minDuration: string; operatorIncluded: boolean; fuelIncluded: boolean; transportDetails: string; available: boolean };
const emptyListing = (): ListingInput => ({ category: 'tractor', name: '', model: '', description: '', photos: '', village: '', taluka: '', district: '', state: 'Maharashtra', amount: '', basis: 'hour_rental', minDuration: '1', operatorIncluded: false, fuelIncluded: false, transportDetails: '', available: true });
function listingPayload(v: ListingInput) { return { category: v.category, name: v.name.trim(), model: v.model.trim(), description: v.description.trim(), photos: v.photos.split('\n').map((x) => x.trim()).filter(Boolean), location: locationPayload(v.village, v.taluka, v.district, v.state), rentalRate: { amount: Number(v.amount), basis: v.basis, currency: 'INR' }, minDuration: Number(v.minDuration), operatorIncluded: v.operatorIncluded, fuelIncluded: v.fuelIncluded, transportDetails: v.transportDetails.trim(), available: v.available, status: v.available ? 'active' : 'paused' }; }

export function NewMachineryPage() {
  const queryClient = useQueryClient(); const navigate = useNavigate(); const { showToast } = useToast(); const [params] = useSearchParams();
  const editId = params.get('edit'); const editing = Boolean(editId);
  const [form, setForm] = useState<ListingInput>(emptyListing());
  const [uploading, setUploading] = useState(false);
  const existing = useQuery({ queryKey: ['machinery', 'edit', editId], queryFn: () => api<{ data: Machinery }>(`/machinery/mine/${editId}`), enabled: Boolean(editId), retry: false });
  useEffect(() => {
    const item = existing.data?.data;
    if (!item) return;
    setForm({ category: item.category, name: item.name, model: item.model ?? '', description: item.description ?? '', photos: (item.photos ?? []).join('\n'), village: item.location?.village ?? '', taluka: item.location?.taluka ?? '', district: item.location?.district ?? '', state: item.location?.state ?? 'Maharashtra', amount: String(item.rentalRate?.amount ?? ''), basis: (item.rentalRate?.basis as ListingInput['basis']) ?? 'hour_rental', minDuration: String(item.minDuration ?? 1), operatorIncluded: Boolean(item.operatorIncluded), fuelIncluded: Boolean(item.fuelIncluded), transportDetails: item.transportDetails ?? '', available: Boolean(item.available) && item.status === 'active' });
  }, [existing.data?.data]);
  const save = useMutation({ mutationFn: () => api<{ data: Machinery }>(editing ? `/machinery/${editId}` : '/machinery', { method: editing ? 'PATCH' : 'POST', body: listingPayload(form) }), onSuccess: async () => { showToast(editing ? 'Equipment listing updated.' : 'Equipment listing published.'); await queryClient.invalidateQueries({ queryKey: ['machinery'] }); await queryClient.invalidateQueries({ queryKey: ['dashboard'] }); navigate('/app/machinery'); }, onError: (e) => showToast((e as Error).message, 'error') });
  const set = <K extends keyof ListingInput>(key: K, value: ListingInput[K]) => setForm((old) => ({ ...old, [key]: value }));
  if (editing && existing.isLoading) return <LoadingState/>;
  if (editing && (existing.error || !existing.data?.data)) return <ErrorState message={(existing.error as Error)?.message ?? 'The listing could not be loaded.'} onRetry={() => void existing.refetch()}/>;
  return <><SectionHeading eyebrow="Equipment marketplace" title={editing ? 'Edit machinery listing' : 'List your machinery'} description="Share the equipment details and rental terms farmers need before requesting a booking." action={<Link className="text-sm font-bold text-forest" to="/app/machinery">← My listings</Link>}/><Card className="max-w-4xl p-5 sm:p-7"><form className="space-y-5" onSubmit={(e) => { e.preventDefault(); if (Number(form.amount) < 0 || !Number.isFinite(Number(form.amount))) return; save.mutate(); }}><div className="grid gap-4 sm:grid-cols-2"><Field label="Equipment category" required><select className={inputClass} value={form.category} onChange={(e) => set('category', e.target.value)}>{[['tractor','Tractor'],['rotavator','Rotavator'],['harvester','Harvester'],['seed_drill','Seed drill'],['sprayer','Sprayer'],['other','Other']].map(([v,l]) => <option value={v} key={v}>{l}</option>)}</select></Field><Field label="Equipment name" required><input className={inputClass} required minLength={2} maxLength={120} value={form.name} onChange={(e) => set('name', e.target.value)} placeholder="e.g. 45 HP Tractor"/></Field><Field label="Model / capacity"><input className={inputClass} maxLength={120} value={form.model} onChange={(e) => set('model', e.target.value)} placeholder="Model or capacity"/></Field><Field label="Rental rate (₹)" required><input className={inputClass} required type="number" min="0" max="10000000" value={form.amount} onChange={(e) => set('amount', e.target.value)}/></Field><Field label="Rate basis" required><select className={inputClass} value={form.basis} onChange={(e) => set('basis', e.target.value as ListingInput['basis'])}><option value="hour_rental">Per hour</option><option value="day_rental">Per day</option><option value="booking">Per booking</option><option value="acre">Per acre</option></select></Field><Field label="Minimum duration (hours)" required><input className={inputClass} required type="number" min="1" max="720" value={form.minDuration} onChange={(e) => set('minDuration', e.target.value)}/></Field></div><Field label="Description"><textarea className={`${inputClass} py-3`} rows={3} maxLength={2000} value={form.description} onChange={(e) => set('description', e.target.value)} placeholder="Condition, capacity, services and any requirements"/></Field><Field label="Equipment image URLs" hint="Upload an image or paste one direct image URL per line."><textarea className={`${inputClass} py-3`} rows={2} value={form.photos} onChange={(e) => set('photos', e.target.value)} placeholder="https://example.com/equipment.jpg"/><div className="mt-2 flex flex-wrap items-center gap-3"><label className={`inline-flex min-h-9 cursor-pointer items-center gap-2 rounded-lg border border-line bg-white px-3 text-xs font-bold text-ink hover:border-forest/30 ${uploading ? 'pointer-events-none opacity-60' : ''}`}><ImagePlus size={15}/>{uploading ? 'Uploading image…' : 'Upload image'}<input className="sr-only" type="file" accept="image/jpeg,image/png,image/webp,image/avif" disabled={uploading} onChange={async (event) => { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; if (file.size > 5 * 1024 * 1024) { showToast('Choose an image smaller than 5 MB.', 'error'); return; } setUploading(true); try { const uploaded = await uploadImage(file); set('photos', [form.photos.trim(), uploaded.url].filter(Boolean).join('\n')); showToast('Image uploaded. Remember to publish the listing to save it.'); } catch (error) { showToast((error as Error).message, 'error'); } finally { setUploading(false); } }}/></label><span className="text-[11px] text-muted">JPEG, PNG, WebP or AVIF · up to 5 MB</span></div></Field><div className="rounded-2xl border border-line p-4"><h3 className="mb-3 font-bold text-ink">Service location</h3><LocationFields village={form.village} setVillage={(v) => set('village',v)} taluka={form.taluka} setTaluka={(v) => set('taluka',v)} district={form.district} setDistrict={(v) => set('district',v)} state={form.state} setState={(v) => set('state',v)}/></div><div className="grid gap-3 sm:grid-cols-2"><label className="flex items-center gap-3 rounded-xl bg-paper p-3 text-sm font-semibold"><input className="h-4 w-4 accent-forest" type="checkbox" checked={form.operatorIncluded} onChange={(e) => set('operatorIncluded', e.target.checked)}/>Operator included</label><label className="flex items-center gap-3 rounded-xl bg-paper p-3 text-sm font-semibold"><input className="h-4 w-4 accent-forest" type="checkbox" checked={form.fuelIncluded} onChange={(e) => set('fuelIncluded', e.target.checked)}/>Fuel included</label></div><Field label="Transport details"><input className={inputClass} maxLength={500} value={form.transportDetails} onChange={(e) => set('transportDetails', e.target.value)} placeholder="Delivery, pickup or transport terms"/></Field><label className="flex items-center gap-3 rounded-xl bg-forest-light/50 p-3 text-sm font-semibold text-forest-dark"><input className="h-4 w-4 accent-forest" type="checkbox" checked={form.available} onChange={(e) => set('available', e.target.checked)}/>Make this listing available for booking</label><div className="flex justify-end gap-2"><Button type="button" variant="secondary" onClick={() => navigate('/app/machinery')}>Cancel</Button><Button type="submit" loading={save.isPending || uploading} disabled={!form.name.trim() || form.amount === '' || uploading}>{editing ? 'Save listing' : 'Publish listing'}</Button></div></form></Card></>;
}

export function MachineryManagePage() {
  const queryClient = useQueryClient(); const { showToast } = useToast(); const navigate = useNavigate();
  const query = useQuery({ queryKey: ['machinery', 'mine'], queryFn: () => api<Page<Machinery>>('/machinery/mine?limit=50'), retry: false });
  const remove = useMutation({ mutationFn: (id: string) => api(`/machinery/${id}`, { method: 'DELETE' }), onSuccess: async () => { showToast('Listing removed.'); await queryClient.invalidateQueries({ queryKey: ['machinery'] }); await queryClient.invalidateQueries({ queryKey: ['dashboard'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const toggle = useMutation({ mutationFn: ({ id, available }: { id: string; available: boolean }) => api(`/machinery/${id}`, { method: 'PATCH', body: { available, status: available ? 'active' : 'paused' } }), onSuccess: async () => { showToast('Listing availability updated.'); await queryClient.invalidateQueries({ queryKey: ['machinery'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  return <><SectionHeading eyebrow="Provider workspace" title="My machinery listings" description="Manage equipment visibility and rental terms." action={<Link to="/app/machinery/new" className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-forest px-4 text-sm font-bold text-white"><Plus size={16}/>Add machinery</Link>}/>{query.isLoading ? <LoadingState/> : query.error ? <ErrorState message={(query.error as Error).message} onRetry={() => void query.refetch()}/> : query.data?.data.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{query.data.data.map((item) => <Card key={item._id} className="overflow-hidden"><div className="relative h-40 bg-gradient-to-br from-forest-light to-paper">{item.photos?.[0] ? <img src={item.photos[0]} alt={item.name} className="h-full w-full object-cover"/> : <div className="grid h-full place-items-center"><Tractor size={48} className="text-forest/50"/></div>}<span className="absolute left-3 top-3"><StatusBadge status={item.status}/></span></div><div className="p-5"><h2 className="text-lg font-extrabold text-ink">{item.name}</h2><p className="mt-1 text-xs capitalize text-muted">{item.category.replace('_',' ')} · {item.model || 'Model not specified'}</p><p className="mt-3 text-lg font-extrabold text-forest">{formatINR(item.rentalRate)}</p><p className="mt-1 text-xs text-muted">{[item.location?.village,item.location?.district].filter(Boolean).join(', ') || 'No service area set'}</p><div className="mt-5 flex flex-wrap gap-2"><Button size="small" variant="secondary" onClick={() => navigate(`/app/machinery/new?edit=${item._id}`)}>Edit</Button><Button size="small" variant="secondary" onClick={() => toggle.mutate({ id: item._id, available: !(item.available && item.status === 'active') })} loading={toggle.isPending}>{item.available && item.status === 'active' ? 'Pause listing' : 'Make available'}</Button><Button size="small" variant="danger" onClick={() => { if (window.confirm('Remove this listing? Active bookings must be resolved first.')) remove.mutate(item._id); }} loading={remove.isPending}><Trash2 size={14}/>Remove</Button></div></div></Card>)}</div> : <EmptyState title="No machinery listings yet" description="Add your tractor, rotavator, harvester or other equipment to receive booking requests." icon={<Tractor size={23}/>}/>}</>;
}

export function BookingsPage() {
  const [params, setParams] = useSearchParams(); const listingId = params.get('listing');
  const me = useQuery({ queryKey: ['me'], queryFn: () => api<{ data: { user: User } }>('/auth/me'), retry: false });
  const user = me.data?.data.user; const canProvider = Boolean(user?.roles.includes('machinery_provider')); const canFarmer = Boolean(user?.roles.includes('farmer'));
  const [as, setAs] = useState<'farmer'|'provider'>(canProvider && !canFarmer ? 'provider' : 'farmer');
  useEffect(() => { if (user) setAs(user.activeRole === 'machinery_provider' ? 'provider' : user.activeRole === 'farmer' ? 'farmer' : user.roles.includes('machinery_provider') && !user.roles.includes('farmer') ? 'provider' : 'farmer'); }, [user?._id, user?.activeRole, user?.roles.join(',')]);
  const query = useQuery({ queryKey: ['bookings', as], queryFn: () => api<Page<Booking>>(`/bookings/mine?as=${as}&limit=50`), enabled: Boolean(user?.roles.includes(as === 'farmer' ? 'farmer' : 'machinery_provider')), retry: false });
  const { showToast } = useToast(); const queryClient = useQueryClient();
  const [start, setStart] = useState(`${today()}T08:00`); const [duration, setDuration] = useState('3'); const [village, setVillage] = useState(''); const [district, setDistrict] = useState(''); const [state, setState] = useState('Maharashtra'); const [intendedUse, setIntendedUse] = useState('');
  const listingQuery = useQuery({ queryKey: ['machinery', 'details', listingId], queryFn: () => api<{ data: Machinery }>(`/machinery/${listingId}`), enabled: Boolean(listingId), retry: false });
  const create = useMutation({ mutationFn: () => api<{ data: Booking }>('/bookings', { method: 'POST', body: { listingId, requestedStart: new Date(start).toISOString(), durationHours: Number(duration), location: locationPayload(village, '', district, state), intendedUse } }), onSuccess: async () => { showToast('Booking request sent to the provider.'); setParams({}); await queryClient.invalidateQueries({ queryKey: ['bookings'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const respond = useMutation({ mutationFn: ({ id, action, note }: { id: string; action: 'accept'|'accept_counter'|'decline'|'cancel'|'complete'; note?: string }) => api(`/bookings/${id}/respond`, { method: 'POST', body: { action, note: note ?? '' } }), onSuccess: async () => { showToast('Booking updated.'); await queryClient.invalidateQueries({ queryKey: ['bookings'] }); await queryClient.invalidateQueries({ queryKey: ['dashboard'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const [counterFor, setCounterFor] = useState(''); const [counterAmount, setCounterAmount] = useState(''); const [counterBasis, setCounterBasis] = useState<'hour_rental'|'day_rental'|'booking'|'acre'>('hour_rental'); const [counterNote, setCounterNote] = useState('');
  const counter = useMutation({ mutationFn: () => api('/bookings/' + counterFor + '/counter-offer', { method: 'POST', body: { rate: { amount: Number(counterAmount), basis: counterBasis, currency: 'INR' }, note: counterNote } }), onSuccess: async () => { showToast('Counter-offer sent.'); setCounterFor(''); await queryClient.invalidateQueries({ queryKey: ['bookings'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const canView = as === 'farmer' ? canFarmer : canProvider;
  return <><SectionHeading eyebrow="Equipment rentals" title="Machinery bookings" description="Review booking requests, respond to terms and keep confirmed rental details on record." action={(canFarmer && canProvider) ? <div className="flex rounded-xl border border-line bg-white p-1"><button className={`rounded-lg px-3 py-2 text-xs font-bold ${as==='farmer'?'bg-forest text-white':'text-muted'}`} onClick={() => setAs('farmer')}>As farmer</button><button className={`rounded-lg px-3 py-2 text-xs font-bold ${as==='provider'?'bg-forest text-white':'text-muted'}`} onClick={() => setAs('provider')}>As provider</button></div> : null}/>
    {listingId && <Card className="mb-5 p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-extrabold text-ink">Request machinery booking</h2>{listingQuery.data?.data && <p className="mt-1 text-sm text-muted">{listingQuery.data.data.name} · {formatINR(listingQuery.data.data.rentalRate)}</p>}</div><button className="text-sm font-bold text-muted underline" onClick={() => setParams({})}>Cancel</button></div>{listingQuery.isLoading ? <LoadingState/> : listingQuery.error ? <ErrorState message={(listingQuery.error as Error).message}/> : <form className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3" onSubmit={(e) => { e.preventDefault(); create.mutate(); }}><Field label="Start date and time" required><input className={inputClass} type="datetime-local" min={`${today()}T00:00`} required value={start} onChange={(e) => setStart(e.target.value)}/></Field><Field label="Duration (hours)" required><input className={inputClass} type="number" min="1" max="720" required value={duration} onChange={(e) => setDuration(e.target.value)}/></Field><Field label="Village / worksite"><input className={inputClass} value={village} onChange={(e) => setVillage(e.target.value)}/></Field><Field label="District" required><input className={inputClass} required value={district} onChange={(e) => setDistrict(e.target.value)}/></Field><Field label="State"><input className={inputClass} value={state} onChange={(e) => setState(e.target.value)}/></Field><Field label="Intended use"><input className={inputClass} maxLength={1000} value={intendedUse} onChange={(e) => setIntendedUse(e.target.value)} placeholder="e.g. Ploughing field 2"/></Field><div className="sm:col-span-2 lg:col-span-3 flex justify-end"><Button type="submit" loading={create.isPending} disabled={!canFarmer}>Send booking request</Button></div></form>}</Card>}
    {!canView ? <EmptyState title={`Enable ${as === 'farmer' ? 'farmer' : 'machinery provider'} role`} description="Use Profile & settings to enable the role needed to view and manage these bookings."/> : query.isLoading ? <LoadingState/> : query.error ? <ErrorState message={(query.error as Error).message} onRetry={() => void query.refetch()}/> : query.data?.data.length ? <div className="space-y-3">{query.data.data.map((item) => { const latest = item.proposalHistory?.[item.proposalHistory.length-1]; const listing = typeof item.listing === 'object' ? item.listing : undefined; return <Card key={item._id} className="p-4 sm:p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-start"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-forest-light text-forest"><PackageCheck size={19}/></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-extrabold text-ink">{listing?.name ?? 'Machinery booking'}</h3><StatusBadge status={item.status}/></div><p className="mt-1 text-xs text-muted">{as==='provider' ? `Requested by ${item.farmer?.name ?? 'farmer'}` : `Provider: ${item.provider?.name ?? 'equipment provider'}`} · {formatDate(item.requestedStart)} · {item.durationHours} hours</p><p className="mt-3 text-lg font-extrabold text-forest">{formatINR(item.agreedRate ?? latest?.wage ?? item.proposedRate)} {item.agreedRate ? '(agreed)' : '(proposed)'}</p><p className="mt-1 text-xs text-muted">{[item.location?.village,item.location?.district,item.location?.state].filter(Boolean).join(', ')}</p>{item.intendedUse && <p className="mt-2 text-sm text-muted">Use: {item.intendedUse}</p>}{latest && <p className="mt-2 rounded-lg bg-paper p-3 text-xs text-muted">Latest counter-offer: {formatINR(latest.wage)}{latest.note ? ` · ${latest.note}` : ''}</p>}</div><div className="flex flex-wrap gap-2 sm:max-w-[190px] sm:flex-col">{as==='provider' && item.status==='requested' && <><Button size="small" onClick={() => respond.mutate({id:item._id,action:'accept'})} loading={respond.isPending}>Accept request</Button><Button size="small" variant="secondary" onClick={() => {setCounterFor(item._id);setCounterAmount(String(item.proposedRate.amount));setCounterBasis((item.proposedRate.basis as typeof counterBasis) ?? 'hour_rental');}}>Counter-offer</Button><Button size="small" variant="ghost" onClick={() => respond.mutate({id:item._id,action:'decline'})} loading={respond.isPending}>Decline</Button></>}{item.status==='negotiation' && latest && String(latest.proposer) !== String(user?._id) && <Button size="small" onClick={() => respond.mutate({id:item._id,action:'accept_counter'})} loading={respond.isPending}>Accept counter</Button>}{['requested','negotiation','confirmed'].includes(item.status) && <Button size="small" variant="secondary" onClick={() => {const reason=window.prompt('Enter a cancellation reason:');if(reason?.trim())respond.mutate({id:item._id,action:'cancel',note:reason.trim()});}} loading={respond.isPending}>Cancel request</Button>}{as==='provider' && item.status==='confirmed' && <Button size="small" onClick={() => respond.mutate({id:item._id,action:'complete'})} loading={respond.isPending}>Mark complete</Button>}</div></div>{counterFor===item._id && <form className="mt-4 grid gap-3 rounded-xl border border-forest/20 bg-forest-light/30 p-4 sm:grid-cols-[1fr_1fr_1.5fr_auto] sm:items-end" onSubmit={(e) => {e.preventDefault();counter.mutate();}}><Field label="Counter rate (₹)" required><input className={inputClass} type="number" min="0" required value={counterAmount} onChange={(e) => setCounterAmount(e.target.value)}/></Field><Field label="Rate basis"><select className={inputClass} value={counterBasis} onChange={(e) => setCounterBasis(e.target.value as typeof counterBasis)}><option value="hour_rental">Per hour</option><option value="day_rental">Per day</option><option value="booking">Per booking</option><option value="acre">Per acre</option></select></Field><Field label="Note"><input className={inputClass} value={counterNote} onChange={(e) => setCounterNote(e.target.value)}/></Field><Button type="submit" loading={counter.isPending}>Send proposal</Button></form>}</Card>; })}</div> : <EmptyState title="No bookings found" description={as==='provider'?'Booking requests from farmers will appear here.':'Your machinery booking requests will appear here.'} icon={<CalendarClock size={23}/>}/>}</>;
}

export function NotificationsPage() {
  const queryClient = useQueryClient(); const { showToast } = useToast();
  const [filter, setFilter] = useState<'all'|'unread'|'read'>('all');
  const query = useQuery({ queryKey: ['notifications', filter], queryFn: () => api<Page<NotificationItem>>(`/notifications?limit=50${filter==='all'?'':`&read=${filter==='read'?'true':'false'}`}`), retry: false });
  const markRead = useMutation({ mutationFn: (id: string) => api(`/notifications/${id}/read`, { method: 'PATCH' }), onSuccess: async () => { await queryClient.invalidateQueries({ queryKey: ['notifications'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const markAll = useMutation({ mutationFn: () => api('/notifications/read-all', { method: 'POST' }), onSuccess: async () => { showToast('All notifications marked as read.'); await queryClient.invalidateQueries({ queryKey: ['notifications'] }); }, onError: (e) => showToast((e as Error).message, 'error') });
  const relatedPath = (item: NotificationItem) => item.relatedType === 'job' ? `/jobs/${item.relatedId}` : item.relatedType === 'booking' ? '/app/bookings' : item.relatedType === 'assignment' ? '/app/assignments' : item.relatedType === 'work_request' ? '/app/invitations' : item.relatedType === 'application' ? '/app/applications' : '/app';
  return <><SectionHeading eyebrow="Activity" title="Notifications" description="Updates from applications, invitations, assignments and machinery bookings." action={<Button variant="secondary" size="small" onClick={() => markAll.mutate()} loading={markAll.isPending}>Mark all read</Button>}/><div className="mb-5 flex gap-2">{(['all','unread','read'] as const).map((v) => <button key={v} onClick={() => setFilter(v)} className={`rounded-xl px-4 py-2 text-xs font-bold capitalize ${filter===v?'bg-forest text-white':'border border-line bg-white text-muted'}`}>{v}</button>)}</div>{query.isLoading ? <LoadingState/> : query.error ? <ErrorState message={(query.error as Error).message} onRetry={() => void query.refetch()}/> : query.data?.data.length ? <div className="space-y-2">{query.data.data.map((item) => <div key={item._id} className={`flex gap-3 rounded-2xl border p-4 ${item.readAt?'border-line bg-white':'border-forest/20 bg-forest-light/30'}`}><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white text-forest"><Bell size={18}/></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="text-sm font-extrabold text-ink">{item.title}</h2>{!item.readAt && <Badge>New</Badge>}</div><p className="mt-1 text-sm leading-6 text-muted">{item.message}</p><p className="mt-2 text-[11px] text-muted">{formatDate(item.createdAt)}</p><div className="mt-3 flex flex-wrap gap-3"><Link className="text-xs font-bold text-forest hover:underline" to={relatedPath(item)}>View related activity</Link>{!item.readAt && <button onClick={() => markRead.mutate(item._id)} className="text-xs font-bold text-muted underline" disabled={markRead.isPending}>Mark read</button>}</div></div></div>)}</div> : <EmptyState title="You're all caught up" description="New activity will be shown here when someone applies, sends an offer or updates a booking." icon={<Bell size={23}/>}/>}</>;
}

export function AdminPage() {
  const { user: currentUser } = useOutletContext<{ user: User }>();
  const queryClient = useQueryClient();
  const { showToast } = useToast();
  const [resolution, setResolution] = useState<Record<string, string>>({});
  const [userSearch, setUserSearch] = useState('');
  const [submittedUserSearch, setSubmittedUserSearch] = useState('');
  const [userReasons, setUserReasons] = useState<Record<string, string>>({});
  const [listingReasons, setListingReasons] = useState<Record<string, string>>({});

  const overview = useQuery({ queryKey: ['admin', 'overview'], queryFn: () => api<{ data: Record<string, number> }>('/admin/overview'), retry: false });
  const reports = useQuery({ queryKey: ['admin', 'reports'], queryFn: () => api<Page<any>>('/admin/reports?limit=30'), retry: false });
  const users = useQuery({ queryKey: ['admin', 'users', submittedUserSearch], queryFn: () => api<Page<any>>(`/admin/users?limit=25${submittedUserSearch ? `&q=${encodeURIComponent(submittedUserSearch)}` : ''}`), retry: false });
  const listings = useQuery({ queryKey: ['admin', 'listings'], queryFn: () => api<Page<any>>('/admin/listings?limit=30'), retry: false });
  const audit = useQuery({ queryKey: ['admin', 'audit'], queryFn: () => api<Page<any>>('/admin/audit?limit=25'), retry: false });

  const afterAdminChange = async (message: string) => {
    showToast(message);
    await queryClient.invalidateQueries({ queryKey: ['admin'] });
  };
  const review = useMutation({
    mutationFn: ({ id, status }: { id: string; status: 'investigating' | 'resolved' | 'dismissed' }) => api(`/admin/reports/${id}`, { method: 'PATCH', body: { status, resolution: resolution[id] ?? '' } }),
    onSuccess: () => afterAdminChange('Report status updated and recorded in the audit log.'), onError: (e) => showToast((e as Error).message, 'error'),
  });
  const userStatus = useMutation({
    mutationFn: ({ id, status }: { id: string; status: 'active' | 'suspended' }) => api(`/admin/users/${id}/status`, { method: 'PATCH', body: { status, reason: (userReasons[id] ?? '').trim() } }),
    onSuccess: () => afterAdminChange('Account status updated and recorded in the audit log.'), onError: (e) => showToast((e as Error).message, 'error'),
  });
  const moderateListing = useMutation({
    mutationFn: ({ id, status }: { id: string; status: 'active' | 'paused' | 'removed' }) => api(`/admin/listings/${id}/moderate`, { method: 'PATCH', body: { status, reason: (listingReasons[id] ?? '').trim() } }),
    onSuccess: () => afterAdminChange('Listing moderation updated and recorded in the audit log.'), onError: (e) => showToast((e as Error).message, 'error'),
  });

  return <>
    <SectionHeading eyebrow="Restricted tools" title="Administration" description="Review operational data and address reports. Only accounts with the admin role can access these APIs." />
    {overview.isLoading ? <LoadingState /> : overview.error ? <ErrorState message={(overview.error as Error).message} onRetry={() => void overview.refetch()} /> : <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[['Users', overview.data?.data.users], ['Active users', overview.data?.data.activeUsers], ['Open jobs', overview.data?.data.openJobs], ['Open reports', overview.data?.data.openReports], ['Machinery listings', overview.data?.data.listings], ['Active listings', overview.data?.data.activeListings], ['Bookings', overview.data?.data.bookings], ['Assignments', overview.data?.data.assignments]].map(([label, value]) => <Card className="p-4" key={String(label)}><p className="text-sm font-semibold text-muted">{label}</p><p className="mt-2 text-3xl font-extrabold text-ink">{Number(value ?? 0).toLocaleString('en-IN')}</p></Card>)}</div>}

    <section className="mt-8">
      <div className="mb-4 flex items-center gap-2"><UserCog size={19} className="text-forest" /><h2 className="text-lg font-extrabold text-ink">User management</h2></div>
      <form className="mb-4 flex flex-col gap-2 sm:flex-row" onSubmit={(event) => { event.preventDefault(); setSubmittedUserSearch(userSearch.trim()); }}><label className="relative flex-1"><span className="sr-only">Search users by name or email</span><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" /><input className={`${inputClass} pl-9`} value={userSearch} onChange={(e) => setUserSearch(e.target.value)} placeholder="Search by name or email" /></label><Button type="submit" variant="secondary"><Search size={15} />Search users</Button></form>
      {users.isLoading ? <LoadingState /> : users.error ? <ErrorState message={(users.error as Error).message} onRetry={() => void users.refetch()} /> : users.data?.data.length ? <div className="space-y-3">{users.data.data.map((item: any) => <Card key={item._id} className="p-4 sm:p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-start"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-extrabold text-ink">{item.name}</h3><StatusBadge status={item.status} /></div><p className="mt-1 break-all text-xs text-muted">{item.email ?? 'No email on file'} · {formatDate(item.createdAt)}</p><div className="mt-2 flex flex-wrap gap-1.5">{(item.roles ?? []).map((role: string) => <Badge key={role}>{role.replaceAll('_', ' ')}</Badge>)}</div></div><div className="w-full lg:max-w-md"><Field label="Reason required for audit" hint="At least 3 characters"><input className={inputClass} value={userReasons[item._id] ?? ''} onChange={(e) => setUserReasons((old) => ({ ...old, [item._id]: e.target.value }))} placeholder="Reason for this account action" /></Field><div className="mt-2 flex flex-wrap gap-2"><Button size="small" variant={item.status === 'suspended' ? 'primary' : 'secondary'} disabled={item.status === 'suspended' || String(item._id) === String(currentUser._id) || (userReasons[item._id] ?? '').trim().length < 3} loading={userStatus.isPending} onClick={() => userStatus.mutate({ id: item._id, status: 'suspended' })}>Suspend</Button><Button size="small" variant="secondary" disabled={item.status === 'active' || (userReasons[item._id] ?? '').trim().length < 3} loading={userStatus.isPending} onClick={() => userStatus.mutate({ id: item._id, status: 'active' })}>Reinstate</Button></div></div></div></Card>)}</div> : <EmptyState title="No users found" description="Try another name or email search." icon={<UserRound size={23} />} />}
    </section>

    <section className="mt-8">
      <div className="mb-4 flex items-center gap-2"><Tractor size={19} className="text-forest" /><h2 className="text-lg font-extrabold text-ink">Machinery listing moderation</h2></div>
      {listings.isLoading ? <LoadingState /> : listings.error ? <ErrorState message={(listings.error as Error).message} onRetry={() => void listings.refetch()} /> : listings.data?.data.length ? <div className="space-y-3">{listings.data.data.map((item: any) => <Card key={item._id} className="p-4 sm:p-5"><div className="flex flex-col gap-4 sm:flex-row"><div className="grid h-20 w-24 shrink-0 place-items-center overflow-hidden rounded-xl bg-forest-light text-forest">{item.photos?.[0] ? <img src={item.photos[0]} alt={item.name} className="h-full w-full object-cover" /> : <Tractor size={25} />}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-extrabold text-ink">{item.name}</h3><StatusBadge status={item.status} /></div><p className="mt-1 text-xs text-muted">{item.category?.replaceAll('_', ' ')} · {item.provider?.providerProfile?.displayName ?? item.provider?.name ?? 'Provider'} · {[item.location?.village, item.location?.district].filter(Boolean).join(', ') || 'Location not provided'}</p><p className="mt-2 text-sm text-muted">{item.description || 'No description provided.'}</p><p className="mt-2 text-sm font-bold text-forest">{formatINR(item.rentalRate)} · {item.available ? 'Provider-marked available' : 'Currently unavailable'}</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto] sm:items-end"><Field label="Moderation reason" hint="At least 3 characters"><input className={inputClass} value={listingReasons[item._id] ?? ''} onChange={(e) => setListingReasons((old) => ({ ...old, [item._id]: e.target.value }))} placeholder="Reason for moderation decision" /></Field><div className="flex flex-wrap gap-2"><Button size="small" variant="secondary" disabled={item.status === 'active' || (listingReasons[item._id] ?? '').trim().length < 3} loading={moderateListing.isPending} onClick={() => moderateListing.mutate({ id: item._id, status: 'active' })}>Activate</Button><Button size="small" variant="secondary" disabled={item.status === 'paused' || (listingReasons[item._id] ?? '').trim().length < 3} loading={moderateListing.isPending} onClick={() => moderateListing.mutate({ id: item._id, status: 'paused' })}>Pause</Button><Button size="small" variant="ghost" disabled={item.status === 'removed' || (listingReasons[item._id] ?? '').trim().length < 3} loading={moderateListing.isPending} onClick={() => { if (window.confirm('Remove this listing from the marketplace?')) moderateListing.mutate({ id: item._id, status: 'removed' }); }}>Remove</Button></div></div></Card>)}</div> : <EmptyState title="No machinery listings" description="Listings that need moderation will appear here." icon={<Tractor size={23} />} />}
    </section>

    <section className="mt-8">
      <div className="mb-4 flex items-center gap-2"><ShieldAlert size={19} className="text-forest" /><h2 className="text-lg font-extrabold text-ink">Report queue</h2></div>
      {reports.isLoading ? <LoadingState /> : reports.error ? <ErrorState message={(reports.error as Error).message} onRetry={() => void reports.refetch()} /> : reports.data?.data.length ? <div className="space-y-3">{reports.data.data.map((report: any) => <Card key={report._id} className="p-4 sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="font-extrabold text-ink">{String(report.reason).replaceAll('_', ' ')}</h3><StatusBadge status={report.status} /></div><p className="mt-1 text-xs text-muted">Reported by {report.reporter?.name ?? 'User'} · {formatDate(report.createdAt)}</p><p className="mt-3 text-sm leading-6 text-muted">{report.details || 'No additional details provided.'}</p><p className="mt-2 text-xs text-muted">Target: {report.reportedUser?.name ?? (report.listing ? 'Machinery listing' : 'Not available')}</p></div></div><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto] sm:items-end"><Field label="Resolution note"><input className={inputClass} value={resolution[report._id] ?? report.resolution ?? ''} onChange={(e) => setResolution((old) => ({ ...old, [report._id]: e.target.value }))} placeholder="Describe the review outcome" /></Field><div className="flex flex-wrap gap-2"><Button size="small" variant="secondary" onClick={() => review.mutate({ id: report._id, status: 'investigating' })} loading={review.isPending}>Investigating</Button><Button size="small" disabled={(resolution[report._id] ?? report.resolution ?? '').trim().length < 3} onClick={() => review.mutate({ id: report._id, status: 'resolved' })} loading={review.isPending}>Resolve</Button><Button size="small" variant="ghost" onClick={() => review.mutate({ id: report._id, status: 'dismissed' })} loading={review.isPending}>Dismiss</Button></div></div></Card>)}</div> : <EmptyState title="No open reports" description="Reports needing review will appear here." icon={<ClipboardCheck size={23} />} />}
    </section>

    <section className="mt-8">
      <div className="mb-4 flex items-center gap-2"><History size={19} className="text-forest" /><h2 className="text-lg font-extrabold text-ink">Recent admin audit history</h2></div>
      {audit.isLoading ? <LoadingState /> : audit.error ? <ErrorState message={(audit.error as Error).message} onRetry={() => void audit.refetch()} /> : audit.data?.data.length ? <div className="overflow-hidden rounded-2xl border border-line bg-white"><div className="divide-y divide-line">{audit.data.data.map((item: any) => <div key={item._id} className="grid gap-1 p-4 sm:grid-cols-[1fr_auto] sm:items-start"><div><p className="text-sm font-bold text-ink">{item.action?.replaceAll('.', ' · ') ?? 'Admin action'} <span className="font-normal text-muted">on {item.entityType}</span></p><p className="mt-1 text-xs text-muted">{item.admin?.name ?? 'Administrator'} · {item.reason || 'No reason supplied'}</p></div><p className="text-[11px] text-muted">{formatDate(item.createdAt)}</p></div>)}</div></div> : <EmptyState title="No audit events yet" description="Administrative changes will be recorded here." icon={<History size={23} />} />}
    </section>
  </>;
}
